/** A sheet as it stood at the end of a date: every change made while the sheet's today was on or
 *  before that date counts, every later change does not, and that date stands in for the sheet's
 *  today. The sheet's rows are rebuilt from the change history (see {@link History}) into the asof
 *  schema, and the work runs against it in place of the live tables, so every rule reads the sheet
 *  as it was. The work must only read: what it writes is thrown away. */
@Service
public class AsOf {

    /** The tables of a sheet's data (keyed by sheet_id) kept in asof_hist and rebuilt into asof. */
    static final List<String> TABLES = List.of("CLAIM", "PERSON", "PERSON_GRADE", "PERSON_HOLD", "PERSON_PATRON",
            "PERSON_WATCH", "PERSON_STATEMENT", "PERIOD", "PERIOD_PERSON_TOTAL", "PERIOD_NUMBER", "RATE",
            "SHEET_SETTING", "SHEET_SETTING_DATED", "SHEET_ROLE", "SHEET_PERMISSION", "SHEET_DELEGATION",
            "CLAIM_LOG", "SHEET_GRADE_TERMS", "SHEET_HOLIDAY", "SHEET_VOID_REASON", "CLAIM_COMMENT", "PERSON_ALIAS",
            "POOL", "POOL_MEMBER", "PLAN", "PLAN_CLAIM", "CLAIM_LINE");

    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;
    private final Map<String, List<String>> columns = new HashMap<>();

    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager) {
        this.jdbc = jdbc;
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The sheets and their "today". A sheet starts with the real date the first time it is loaded;
 * from then on {@link #today(String)} is the only date the app uses for that sheet — never the
 * real clock.
 */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    /**
     * The sheet's next claim number: the next after the last number given anywhere in the sheet's
     * tree (see {@link #treeOf}), so the sheets of a tree share one sequence; 1 for a tree's first.
     * The rows of the tree's sheets stay locked until the transaction ends, so two claims opened at
     * once get different numbers, and a number is never given twice.
     */

