-- How many sheet-wide numbers each sheet has given out within a fiscal year (`fy` is the year,
-- yyyy, of FY<yyyy>): a claim opened sheet-wide is numbered FY<yyyy>-<n>, the sheets of a tree
-- sharing one sequence per fiscal year. Numbers given before this (plain "7") stay as they are.
CREATE TABLE fiscal_number (
    sheet_id VARCHAR(200) NOT NULL,
    fy       INT          NOT NULL,
    given    BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, fy)
);
EOF
python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/sheet/Sheets.java'
s=open(p).read()
anchor='''    /** The sheets of the sheet's tree,'''
add='''    /**
     * The sheet's next number within a fiscal year (the yyyy of FY<yyyy>): the next after the last
     * given in that fiscal year anywhere in the sheet's tree (see {@link #treeOf}), so the sheets of a
     * tree share one sequence per fiscal year; 1 for its first. Locks the tree's rows as
     * {@link #nextClaimNumber} does, so a number is never given twice.
     */
    public long nextFiscalNumber(String sheetId, int fy) {
        today(sheetId);
        java.util.List<String> tree = new java.util.ArrayList<>(treeOf(sheetId));
        java.util.Collections.sort(tree);
        long last = 0;
        for (String sheet : tree) {
            jdbc.update("UPDATE sheet SET claim_numbers = claim_numbers WHERE id = ?", sheet);
            Long given = jdbc.queryForList("SELECT given FROM fiscal_number WHERE sheet_id = ? AND fy = ?", Long.class,
                    sheet, fy).stream().findFirst().orElse(0L);
            last = Math.max(last, given == null ? 0 : given);
        }
        jdbc.update("MERGE INTO fiscal_number (sheet_id, fy, given) KEY (sheet_id, fy) VALUES (?, ?, ?)",
                sheetId, fy, last + 1);
        return last + 1;
    }

'''
assert anchor in s
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)

p='src/main/java/net/officefloor/hq/app/claim/ClaimNumbers.java'
s=open(p).read()
s=s.replace(""" *  (<period name>-<n>), or X-<n> when it falls in none; otherwise it takes the sheet's next number. */""",
""" *  (<period name>-<n>), or X-<n> when it falls in none; otherwise it takes the next number within
 *  the fiscal year its due-by falls in (FY<yyyy>-<n>, counting from 1 each fiscal year, the sequence
 *  shared across the sheet's tree). */""")
s=s.replace("""            return String.valueOf(sheets.nextClaimNumber(sheetId));""",
"""            int fy = fiscalYear(claim.getDueBy(), settings.fiscalStartMonth(sheetId));
            return "FY" + fy + "-" + sheets.nextFiscalNumber(sheetId, fy);""")
s=s.rstrip()[:-1]+"""
    /** The fiscal year (the yyyy of FY<yyyy>, the calendar year its first day falls in) a date is in. */
    static int fiscalYear(LocalDate date, int startMonth) {
        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
    }
}
"""
open(p,'w').write(s)
EOF
